    case 32: /* PROCEDURE */
    case 33: /* TRIGGER */
    case 34: /* USER */
    case 35: /* ROLE */
    case 36: /* RESOURCE */
    case 37: /* SERVER */
    case 38: /* LOGFILE */
    case 39: /* TABLESPACE */
    case 40: /* UNDO */
    case 41: /* DROP */
    case 42: /* TABLES */
    case 43: /* PREPARE */
    case 44: /* ALTER */
    case 45: /* INSTANCE */
    case 46: /* RENAME */
    case 47: /* TRUNCATE */
    case 48: /* LOAD */
    case 49: /* DATA */
    case 50: /* XML */
    case 51: /* START */
    case 52: /* TRANSACTION */
    case 53: /* REPLICA */
    case 54: /* SLAVE */
    case 55: /* GROUP_REPLICATION */
    case 56: /* SAVEPOINT */
    case 57: /* RELEASE */
    case 58: /* LOCK */
    case 59: /* UNLOCK */
    case 60: /* ANALYZE */
    case 61: /* CHECK */
    case 62: /* CHECKSUM */
    case 63: /* OPTIMIZE */
    case 64: /* REPAIR */
    case 65: /* LOCAL */
    case 66: /* NO_WRITE_TO_BINLOG */
    case 67: /* INSTALL */
    case 68: /* UNINSTALL */
    case 69: /* COMPONENT */
    case 70: /* PLUGIN */
    case 71: /* IMPORT */
    case 72: /* CACHE */
    case 73: /* KILL */
    case 74: /* CONNECTION */
    case 75: /* QUERY */
    case 76: /* DEALLOCATE */
    case 77: /* RESET */
    case 78: /* BINARY */
